python3 << 'PYEOF'
import json

with open('/app/output/analysis_data.json') as f:
    data = json.load(f)

# Read the HTML template
with open('/app/output/final_report.html') as f:
    html = f.read()

# Replace the fetch with inline data
old_script = """    <script>
    // Load and render analysis data
    fetch('/app/output/analysis_data.json')
        .then(r => r.json())
        .then(data => {
            renderPriceChart(data.price_chart_data);
            renderVolChart(data.vol_chart_data);
            renderDrawdownChart(data.drawdown_chart);
            renderVolumeChart(data.volume_chart);
            renderAnnualReturns(data.annual_returns);
            renderAnnualTable(data.annual_data);
        })
        .catch(e => console.error('Error loading data:', e));"""

new_script = f"""    <script>
    // Embedded analysis data - self-contained report
    const data = {json.dumps(data)};

    document.addEventListener('DOMContentLoaded', function() {{
        renderPriceChart(data.price_chart_data);
        renderVolChart(data.vol_chart_data);
        renderDrawdownChart(data.drawdown_chart);
        renderVolumeChart(data.volume_chart);
        renderAnnualReturns(data.annual_returns);
        renderAnnualTable(data.annual_data);
    }});"""

html = html.replace(old_script, new_script)

with open('/app/output/final_report.html', 'w') as f:
    f.write(html)

print("HTML updated with embedded data")
PYEOF

